    const groupNames = config['proxy-groups'].map(g => g.name);
    console.log('[DEBUG] Group names:', groupNames.join(', '));

    // 找出 FREE 组（如果有）
    const freeGroup = config['proxy-groups'].find(g => g.name === 'FREE');

    if (freeGroup) {
      console.log('[DEBUG] Found FREE group');
      console.log('[DEBUG] FREE proxies before fix:', freeGroup.proxies ? freeGroup.proxies.join(', ') : 'none');

      if (freeGroup.proxies) {
        // 从其他所有代理组中移除 FREE 引用（避免循环）
        let removedCount = 0;
        config['proxy-groups'].forEach(group => {
          if (group.name !== 'FREE' && group.proxies) {
            const originalLength = group.proxies.length;
            group.proxies = group.proxies.filter(p => p !== 'FREE');
            removedCount += originalLength - group.proxies.length;
          }
        });
        console.log('[DEBUG] Removed', removedCount, 'FREE references from other groups');
      }
    } else {
      console.log('[DEBUG] No FREE group found');
    }
  }

  return config;
}
